commands.command:
rm -f /var/lib/inventory/t1
setpriv --reuid 103 --regid 104 --clear-groups --no-new-privs bwrap \
  --unshare-all --die-with-parent \
  --ro-bind / / \
  --bind /var/lib/inventory /var/lib/inventory \
  --proc /proc --dev /dev --tmpfs /tmp \
  --chdir /var/lib/inventory --new-session \
  -- sh -c '
    echo "--- try write outside confined dir ---";
    touch /tmp/should_fail 2>&1 || echo "blocked: /tmp write failed as expected? (tmpfs mounted so may succeed, thats fine, its not persistent host fs)";
    touch /root/should_fail 2>&1 || echo "blocked write to /root as expected";
    touch /etc/should_fail 2>&1 || echo "blocked write to /etc as expected";
    echo "--- no_new_privs check ---";
    grep NoNewPrivs /proc/self/status;
    echo "--- confined write ---";
    touch /var/lib/inventory/ok_write && echo "wrote ok_write successfully";
  '
ls -la /var/lib/inventory
